import pandas as pd
import numpy as np
from scipy import stats

# Load all available experiments
dfs = {}
for exp_id in [1, 5, 6]:
    fname = eval(f"experiment_{exp_id}_csv")
    dfs[f"exp{exp_id}"] = pd.read_csv(fname)
    print(f"\n=== Experiment {exp_id} ===")
    print(f"Columns: {list(dfs[f'exp{exp_id}'].columns)}")
    print(f"Shape: {dfs[f'exp{exp_id}'].shape}")

    # Check for inhibitor column variations
    for col in dfs[f"exp{exp_id}"].columns:
        if "inhib" in col.lower() or "corros" in col.lower():
            print(f"  Inhibitor column '{col}': unique values = {dfs[f'exp{exp_id}'][col].unique()}")

    print(dfs[f"exp{exp_id}"].describe().round(2))

# Try to find inhibitor-related columns across all experiments
print("\n\n=== Searching for inhibitor dose column ===")
for exp_id in [1, 5, 6]:
    for col in dfs[f"exp{exp_id}"].columns:
        if "inhib" in col.lower() or "corros" in col.lower():
            print(f"\nExp {exp_id}, column '{col}':")
            print(f"  Unique values: {sorted(dfs[f'exp{exp_id}'][col].unique())}")
            if len(dfs[f"exp{exp_id}"][col].unique()) > 1:
                # Group by dose
                grouped = dfs[f"exp{exp_id}"].groupby(col)["WaterClarityScore"].agg(["mean","std","count"])
                print(grouped.round(2))

# Also check MetalColorimetry by inhibitor dose
print("\n\n=== MetalColorimetry by inhibitor dose ===")
for exp_id in [1, 5, 6]:
    for col in dfs[f"exp{exp_id}"].columns:
        if "inhib" in col.lower() or "corros" in col.lower():
            if len(dfs[f"exp{exp_id}"][col].unique()) > 1:
                grouped_metal = dfs[f"exp{exp_id}"].groupby(col)["MetalColorimetry"].agg(["mean","std","count"])
                print(f"\nExp {exp_id}, column '{col}' -> MetalColorimetry:")
                print(grouped_metal.round(2))

